+document.addEventListener('DOMContentLoaded', () => {
+    const form = document.getElementById('contactForm');
+    const statusDiv = document.getElementById('formStatus');
+
+    const fields = {
+        fullName: {
+            input: document.getElementById('fullName'),
+            error: document.getElementById('nameError'),
+            validate: (value) => {
+                if (!value.trim()) return 'Full name is required.';
+                return '';
+            }
+        },
+        email: {
+            input: document.getElementById('email'),
+            error: document.getElementById('emailError'),
+            validate: (value) => {
+                if (!value.trim()) return 'Email address is required.';
+                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+                if (!emailRegex.test(value)) return 'Please enter a valid email address.';
+                return '';
+            }
+        },
+        phone: {
+            input: document.getElementById('phone'),
+            error: document.getElementById('phoneError'),
+            validate: (value) => {
+                if (!value.trim()) return ''; // Optional
+                const phoneRegex = /^\(?([0-9]{3})\)?[-. ]?([0-9]{3})[-. ]?([0-9]{4})$/;
+                if (!phoneRegex.test(value)) return 'Please enter a valid phone number (e.g., (123) 456-7890).';
+                return '';
+            }
+        }
+    };
+
+    const validateField = (fieldName) => {
+        const field = fields[fieldName];
+        const errorMessage = field.validate(field.input.value);
+        
+        if (errorMessage) {
+            field.error.textContent = errorMessage;
+            field.input.setAttribute('aria-invalid', 'true');
+            field.input.setAttribute('aria-describedby', field.input.getAttribute('aria-describedby')?.includes(field.error.id) 
+                ? field.input.getAttribute('aria-describedby') 
+                : `${field.input.getAttribute('aria-describedby') || ''} ${field.error.id}`.trim());
+            return false;
+        } else {
+            field.error.textContent = '';
+            field.input.removeAttribute('aria-invalid');
+            // Keep helper text in describedby if it exists
+            const helperId = fieldName === 'phone' ? 'phoneHelper' : '';
+            if (helperId) {
+                field.input.setAttribute('aria-describedby', helperId);
+            } else {
+                field.input.removeAttribute('aria-describedby');
+            }
+            return true;
+        }
+    };
+
+    // Real-time validation
+    Object.keys(fields).forEach(fieldName => {
+        fields[fieldName].input.addEventListener('blur', () => validateField(fieldName));
+        fields[fieldName].input.addEventListener('input', () => {
+            if (fields[fieldName].input.getAttribute('aria-invalid') === 'true') {
+                validateField(fieldName);
+            }
+        });
+    });
+
+    form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        
+        let isValid = true;
+        let firstInvalidField = null;
+
+        Object.keys(fields).forEach(fieldName => {
+            if (!validateField(fieldName)) {
+                isValid = false;
+                if (!firstInvalidField) {
+                    firstInvalidField = fields[fieldName].input;
+                }
+            }
+        });
+
+        if (!isValid) {
+            firstInvalidField.focus();
+            statusDiv.textContent = 'Please correct the errors in the form.';
+            statusDiv.className = 'form-status error';
+            return;
+        }
+
+        // Simulate form submission
+        statusDiv.textContent = 'Sending...';
+        statusDiv.className = 'form-status';
+        statusDiv.style.display = 'block';
+
+        setTimeout(() => {
+            statusDiv.textContent = 'Thank you! Your message has been sent successfully.';
+            statusDiv.className = 'form-status success';
+            form.reset();
+            // Reset aria-invalid states
+            Object.keys(fields).forEach(fieldName => {
+                fields[fieldName].input.removeAttribute('aria-invalid');
+                const helperId = fieldName === 'phone' ? 'phoneHelper' : '';
+                if (helperId) {
+                    fields[fieldName].input.setAttribute('aria-describedby', helperId);
+                } else {
+                    fields[fieldName].input.removeAttribute('aria-describedby');
+                }
+            });
+        }, 1000);
+    });
+});
+
